import{_ as t,o,c as a,a2 as s}from"./chunks/framework.BN3Eol-0.js";const u=JSON.parse(`{"title":"UXD-045 — INDEX rows: the type is a 14 px glyph with a tooltip, the name keeps the row's width","description":"","frontmatter":{},"headers":[],"relativePath":"uxs/decisions/UXD-045-index-row-type-is-a-glyph-with-a-tooltip.md","filePath":"uxs/decisions/UXD-045-index-row-type-is-a-glyph-with-a-tooltip.md"}`),i={name:"uxs/decisions/UXD-045-index-row-type-is-a-glyph-with-a-tooltip.md"};function n(r,e,l,h,d,c){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="uxd-045-—-index-rows-the-type-is-a-14-px-glyph-with-a-tooltip-the-name-keeps-the-row-s-width" tabindex="-1">UXD-045 — INDEX rows: the type is a 14 px glyph with a tooltip, the name keeps the row&#39;s width <a class="header-anchor" href="#uxd-045-—-index-rows-the-type-is-a-14-px-glyph-with-a-tooltip-the-name-keeps-the-row-s-width" aria-label="Permalink to &quot;UXD-045 — INDEX rows: the type is a 14 px glyph with a tooltip, the name keeps the row&#39;s width&quot;">​</a></h1><ul><li><strong>Status</strong>: accepted (built; unit and e2e tests green, see Verification)</li><li><strong>Date</strong>: 2026-11-15</li><li><strong>Decider</strong>: the operator, 2026-11-15 — &quot;Maybe the type of item should be a small item with a tooltip, and we get the space for the full name to render.&quot;</li><li><strong>Answers</strong>: L46 follow-up (names cut at &quot;M13 · Hercules G…&quot;)</li><li><strong>Builds on</strong>: <a href="./UXD-017-one-index-on-every-scale">UXD-017</a> (one INDEX, one row component), <a href="./UXD-025-lists-carry-a-round-photo">UXD-025</a> (the 28 px photo that took 36 px from the name)</li><li><strong>Changes</strong>: <code>src/lib/explore/index-kind-glyph.ts</code> (kind to glyph), <code>src/lib/components/IndexKindGlyph.svelte</code> (the 14 drawings), <code>ScaleIndex.svelte</code> (the glyph, <code>data-tip</code>, hidden text), <code>src/lib/styles/index-panel.css</code> (<code>.si-kind</code>), tests (<code>index-kind-glyph.test.ts</code>, <code>scale-index.spec.ts</code>). No string, image or dependency changed.</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>The type text (&quot;Globular cluster&quot;, &quot;Star-forming region&quot;) sat beside the name and kept up to 45% of the 320 px row. After the flex fix 7d24947025a 44 of the 209 neighbourhood rows still cut the name; before it 98 did.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><ol><li><strong>The type is a glyph</strong> at the row&#39;s end (after the name, before the badges), 14 px, <code>currentColor</code> on <code>--color-state</code> (the colour the text had), on every scale except the solar system (its two-line meta is distance and size, not a type) and the Local Group (its meta is the group line).</li><li><strong>14 drawings, none reused</strong>: no object-type glyph existed in the repo (the scale and route glyphs are 48 px level and route cards): star, galaxy (also satellite and dwarf galaxies), cluster (star cluster, galaxy cluster, concentration), globular, nebula (also star-forming region, dark nebula, cloud), shell (planetary nebula, supernova remnant), group, network (supercluster), wall, void, attractor, black hole, spiral arm, other. The exact type is always the label; a glyph that shares a type with a sibling is never the only carrier.</li><li><strong>Tooltip and accessible name.</strong> The exact localized type is <code>data-tip</code>, drawn as a small card inside the row (so the list&#39;s scroll box does not clip it) on hover of the glyph and on keyboard focus of the row; for a screen reader it is hidden text after the name (&quot;M13 · Hercules Globular Cluster, Globular cluster&quot;). Meaning is never colour-only.</li><li><strong>A star keeps its constellation as text</strong> before its star glyph: the constellation is information, not the type.</li><li>Row height and photo slot are unchanged. RTL follows the row&#39;s direction (the tooltip opens toward the name on both sides).</li></ol><h2 id="not-done-here" tabindex="-1">Not done here <a class="header-anchor" href="#not-done-here" aria-label="Permalink to &quot;Not done here&quot;">​</a></h2><ul><li>No tooltip on touch: a tap selects the row; the type is in the panel that opens. The glyph alone does not say the type to a sighted touch reader.</li><li>The Local Group rows still show the group line, not a type glyph.</li></ul><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><p>31 of 209 neighbourhood rows still cut the name at 320 px (28 deep-sky names long in themselves, 3 stars with a constellation); 44 before this change. <code>index-kind-glyph.test.ts</code> 22 passed; <code>scale-index.spec.ts</code> 45 passed on desktop-chromium against the shared dev server.</p>',10)])])}const g=t(i,[["render",n]]);export{u as __pageData,g as default};
